import json,html
ROOT=Path(__file__).resolve().parents[1];d=ROOT/'diagnostics';before=json.loads((d/'before-pipeline.json').read_text());after=json.loads((d/'after-pipeline.json').read_text());body=[]
labels={'root':'루트 / 체중 중심 기준','pelvis.L':'왼쪽 골반','pelvis.R':'오른쪽 골반','spine05':'하부 척추 1','spine04':'하부 척추 2','spine03':'중간 척추','spine02':'상부 척추','spine01':'가슴','clavicle.L':'왼쪽 쇄골','clavicle.R':'오른쪽 쇄골','shoulder01.L':'왼쪽 어깨','shoulder01.R':'오른쪽 어깨','neck01':'목','head':'머리'};names={'Walk':'전술 보행','Sprint':'전력 질주','AimWalk':'조준 이동','MovingFire':'이동 사격','Reload':'재장전'};sections=[]
